using System;using System.IO;using Newtonsoft.Json.Linq;using SpatialWallpaper.Content;using SpatialWallpaper.Sdk.Native;
static class NativeStoreChecks {
 static int count;static void Need(bool ok,string why){if(!ok)throw new Exception(why);count++;}
 static void Refuse(Action action){try{action();}catch(InvalidDataException){count++;return;}throw new Exception("expected-native-admission-rejection");}
 static void Main(string[] args){try{Run(args);}catch(Exception error){for(var e=error;e!=null;e=e.InnerException){Console.Error.WriteLine(e.GetType().FullName);Console.Error.WriteLine(e.Message);}Environment.Exit(1);}}
 static void Run(string[] args){string root=args[0],stage=Path.Combine(root,"staging");Directory.CreateDirectory(stage);var store=new ContentStore(Path.Combine(root,"library"),stage);var platform=new NativePlatformCatalog(File.ReadAllText(args[1]));
 string Stage(string file){string id=Guid.NewGuid().ToString("D");File.Copy(file,Path.Combine(stage,id+".spatial"));return id;}
 for(int i=2;i<7;i++){var package=NativePackage.Validate(args[i]);var first=store.ImportNative(Stage(args[i]),platform);string work=(string)first["work_id"],revision=(string)first["revision_id"];Need(work==package.WorkId,"stable-author-guid-lost");Need(store.OpenNativeBuild(work,revision,platform).BuildId==package.BuildId,"installed-native-bytes-not-admitted");var duplicate=store.ImportNative(Stage(args[i]),platform);Need((bool)duplicate["duplicate"]&&(string)duplicate["revision_id"]==revision,"duplicate-created-revision");}
 var selected=NativePackage.Validate(args[2]);string w=selected.WorkId,old=store.Latest(w);store.RecordApplied("offline-display-1",w,old);var applied=store.Snapshot["applied"].DeepClone();var update=store.ImportNative(Stage(args[7]),platform,w,old);string fresh=(string)update["revision_id"];Need(fresh!=old&&store.Latest(w)==fresh,"update-did-not-retain-stable-work");Need(JToken.DeepEquals(applied,store.Snapshot["applied"]),"update-switched-playing-revision");Need(store.OpenNativeBuild(w,old,platform).BuildId==selected.BuildId,"update-destroyed-old-revision");string before=store.Snapshot.ToString();Refuse(()=>store.ImportNative(Stage(args[2]),platform,w,old));Need(store.Snapshot.ToString()==before,"stale-update-mutated-store");Refuse(()=>store.ImportNative(Stage(args[3]),platform,w,fresh));Need(store.Snapshot.ToString()==before,"cross-work-update-mutated-store");Refuse(()=>store.ImportNative(Stage(args[8]),platform,w,fresh));Need(store.Snapshot.ToString()==before,"forged-scene-mutated-store");var reopened=new ContentStore(Path.Combine(root,"library"),stage);Need(JToken.DeepEquals(reopened.Snapshot,store.Snapshot),"native-library-not-durable");File.WriteAllText(Path.Combine(root,"result.json"),new JObject{{"passed",true},{"checks",count},{"stable_guid",true},{"old_playing_revision_retained",true},{"rejected_stale_cross_work_forged_scene",true},{"durable_reopen",true},{"scope","actual five native archives and core library transactions; no GUI, sound or physical display claim"}}.ToString());
 }
}
